package com.aditya.fefo.unit; import com.aditya.fefo.domain.*; import org.junit.jupiter.api.*; import java.time.*; import static org.junit.jupiter.api.Assertions.*; class ReservationLifecycleTest {Product p=new Product("S","P","");@Test void reservedCanConfirm(){var r=new Reservation("R",p,1,Instant.now().plusSeconds(60),null);r.confirm();assertEquals(ReservationStatus.CONFIRMED,r.getStatus());}@Test void reservedCanCancel(){var r=new Reservation("R",p,1,Instant.now().plusSeconds(60),null);r.cancel();assertEquals(ReservationStatus.CANCELLED,r.getStatus());}@Test void confirmedCannotCancel(){var r=new Reservation("R",p,1,Instant.now().plusSeconds(60),null);r.confirm();assertThrows(IllegalStateException.class,r::cancel);}@Test void expiryCheck(){var r=new Reservation("R",p,1,Instant.now().minusSeconds(1),null);assertTrue(r.isHoldExpired(Instant.now()));}}
